import { defineStore } from 'pinia';
import type { DocNetEmail, DocNetEmailOrchestrationStatus } from 'src/@types/docnet';
import DocNetEmailService from 'src/services/docnet/DocNetEmailService';
import { useDocNetSettingsStore } from './docnet-settings.store';
import { mockEmails } from 'src/mocks/docnet/emails';

const emailApi = new DocNetEmailService();

export const useDocNetEmailStore = defineStore('docnet_email', {
  state: () => ({
    emails: [] as DocNetEmail[],
    selectedEmailId: null as string | null,
    loading: false,
    page: 1,
    limit: 50,
    total: 0,
    unreadTotal: 0,
    // Server-side search — trimmed, case-insensitive substring against
    // subject, body, and sender (matches /missions and /issues, which
    // search title/name + description). Caller debounces user input.
    searchFilter: '' as string,
    _lastFetchParams: undefined as { read?: boolean } | undefined,
    // Tracks the search term of the last successful fetch so that a new
    // search triggers a full replace (not a merge) — otherwise emails
    // that fell out of the filter would linger in the rendered list.
    _lastSearchFilter: '' as string,
  }),

  getters: {
    unreadCount(state): number {
      return state.unreadTotal;
    },

    emailsByMission:
      (state) =>
      (missionId: string): DocNetEmail[] =>
        state.emails.filter((e: DocNetEmail) => e.mission_id === missionId),

    emailsByClassification:
      (state) =>
      (type: string): DocNetEmail[] =>
        state.emails.filter((e: DocNetEmail) => e.classification === type),

    selectedEmail(state): DocNetEmail | null {
      if (!state.selectedEmailId) return null;
      return state.emails.find((e: DocNetEmail) => e.id === state.selectedEmailId) ?? null;
    },

    totalPages(state): number {
      return Math.max(1, Math.ceil(state.total / state.limit));
    },
  },

  actions: {
    async fetchEmails(params?: { read?: boolean; page?: number; forceReplace?: boolean }): Promise<void> {
      const settings = useDocNetSettingsStore();
      if (settings.useMockData) { this.emails = mockEmails; this.total = mockEmails.length; return; }
      // When called with no params (e.g. WebSocket refetch), replay the last query
      const readFilter = params?.read ?? (params === undefined ? this._lastFetchParams?.read : undefined);
      const sameFilter = readFilter === this._lastFetchParams?.read;
      const samePage = (params?.page ?? this.page) === this.page;
      // ``isRefresh`` is for WS-driven background syncs: same page + same
      // read filter → merge new items in place so the user's scroll and
      // selection survive. Search changes must bypass this because
      // ``_mergeEmails`` never removes rows that fell out of the filter,
      // so narrowing searches would leave stale matches visible until a
      // folder switch forced a full replace.
      const isRefresh =
        !params?.forceReplace
        && this.emails.length > 0
        && sameFilter
        && samePage
        && this._lastSearchFilter === this.searchFilter;
      if (!isRefresh) this.loading = true;
      try {
        const page = params?.page ?? this.page;
        const skip = (page - 1) * this.limit;
        const result = await emailApi.fetchEmails({
          read: readFilter,
          skip,
          limit: this.limit,
          search: this.searchFilter || undefined,
        });
        if (isRefresh) {
          this._mergeEmails(result.items);
        } else {
          this.emails = result.items;
        }
        this.total = result.total;
        this.unreadTotal = result.unread_total;
        this.page = page;
        this._lastFetchParams = { read: readFilter };
        this._lastSearchFilter = this.searchFilter;
      } finally {
        this.loading = false;
      }
    },

    async goToPage(page: number, params?: { read?: boolean }): Promise<void> {
      await this.fetchEmails({ ...params, page });
    },

    async setSearchFilter(search: string, folderParams?: { read?: boolean }): Promise<void> {
      // No-op when the trimmed value is unchanged — debounced callers often
      // push the same value repeatedly once the user pauses typing.
      const trimmed = search?.trim() ?? '';
      if (trimmed === this.searchFilter) return;
      this.searchFilter = trimmed;
      this.page = 1;
      await this.fetchEmails({ ...folderParams, page: 1 });
    },

    async fetchEmailDetail(id: string): Promise<DocNetEmail> {
      const email = await emailApi.fetchEmail(id);
      const idx = this.emails.findIndex((e: DocNetEmail) => e.id === id);
      if (idx !== -1) {
        this.emails[idx] = email;
      }
      return email;
    },

    async markAsRead(id: string): Promise<void> {
      const email = this.emails.find((e: DocNetEmail) => e.id === id);
      if (email && !email.read) {
        email.read = true;
        if (this.unreadTotal > 0) this.unreadTotal--;
      }
      await emailApi.markRead(id);
    },

    async linkToMission(emailId: string, missionId: string): Promise<void> {
      await emailApi.patchEmail(emailId, { mission_id: missionId });
      const email = this.emails.find((e: DocNetEmail) => e.id === emailId);
      if (email) email.mission_id = missionId;
    },

    async setOrchestrationStatus(emailId: string, status: DocNetEmailOrchestrationStatus): Promise<void> {
      await emailApi.patchEmail(emailId, { orchestration_status: status });
      const email = this.emails.find((e: DocNetEmail) => e.id === emailId);
      if (email) email.orchestration_status = status;
    },

    resetPagination(): void {
      this.page = 1;
      this.total = 0;
      this.emails = [];
    },

    _mergeEmails(incoming: DocNetEmail[]): void {
      const existingMap = new Map(this.emails.map((e) => [e.id, e]));

      // Update existing emails in-place
      for (const newEmail of incoming) {
        const existing = existingMap.get(newEmail.id);
        if (existing) {
          Object.assign(existing, newEmail);
        }
      }

      // Prepend new emails that don't exist yet
      const newEmails = incoming.filter((e) => !existingMap.has(e.id));
      if (newEmails.length > 0) {
        this.emails.unshift(...newEmails);
      }
    },
  },
});
